create table if not exists public.reward_catalog (id text primary key,name text not null,description text not null,category text not null,cost_points integer not null check(cost_points>0),stock integer check(stock is null or stock>=0),fulfillment_type text not null default 'digital' check(fulfillment_type in('digital','pickup')),is_active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.reward_redemptions (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,reward_id text references public.reward_catalog(id) on delete set null,reward_name text not null,points_spent integer not null check(points_spent>0),status text not null default 'processing' check(status in('processing','completed','cancelled')),redemption_code text not null unique,redemption_key uuid not null unique,created_at timestamptz not null default now(),fulfilled_at timestamptz);
create index if not exists reward_redemptions_user_created_idx on public.reward_redemptions(user_id,created_at desc);
insert into public.reward_catalog(id,name,description,category,cost_points,stock,fulfillment_type,sort_order) values ('premium-book','Buku Premium: Perahu Kertas','Buka Perahu Kertas di rak Romance dan baca tanpa batas.','Bacaan digital',750,null,'digital',1),('premium-horror-jeritan-tengah-malam','Buku Premium: Jeritan Tengah Malam','Buka antologi cerpen Jeritan Tengah Malam di rak Horror dan baca tanpa batas.','Bacaan digital',750,null,'digital',2),('beng-beng','Beng-Beng','Camilan renyah untuk menemani sesi membacamu berikutnya.','Camilan',350,50,'pickup',3) on conflict(id) do update set name=excluded.name,description=excluded.description,category=excluded.category,cost_points=excluded.cost_points,fulfillment_type=excluded.fulfillment_type,sort_order=excluded.sort_order;
alter table public.reward_catalog enable row level security; alter table public.reward_redemptions enable row level security;
drop policy if exists "Authenticated users read active rewards" on public.reward_catalog; create policy "Authenticated users read active rewards" on public.reward_catalog for select to authenticated using(is_active=true);
drop policy if exists "Users read own redemptions" on public.reward_redemptions; create policy "Users read own redemptions" on public.reward_redemptions for select to authenticated using(auth.uid()=user_id);
drop policy if exists "Admins read all redemptions" on public.reward_redemptions; create policy "Admins read all redemptions" on public.reward_redemptions for select to authenticated using(public.is_admin());
create or replace function public.redeem_catalog_reward(p_reward_id text,p_redemption_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_profile public.profiles;v_reward public.reward_catalog;v_redemption public.reward_redemptions;v_spent integer;v_balance integer;begin if auth.uid() is null then raise exception 'Silakan masuk untuk menukar poin.';end if;if p_redemption_key is null then raise exception 'Kunci penukaran tidak valid.';end if;select * into v_redemption from public.reward_redemptions where redemption_key=p_redemption_key and user_id=auth.uid();if found then return jsonb_build_object('redemption',to_jsonb(v_redemption),'balance',0,'remaining_stock',null);end if;select * into v_profile from public.profiles where id=auth.uid() for update;if not found or v_profile.status<>'active' then raise exception 'Profil aktif tidak ditemukan.';end if;select * into v_reward from public.reward_catalog where id=p_reward_id and is_active=true for update;if not found then raise exception 'Hadiah tidak tersedia.';end if;if v_reward.stock is not null and v_reward.stock<=0 then raise exception 'Stok hadiah sudah habis.';end if;select coalesce(sum(points_spent),0)::integer into v_spent from public.reward_redemptions where user_id=auth.uid() and status<>'cancelled';v_balance:=v_profile.points-v_spent;if v_balance<v_reward.cost_points then raise exception 'Poin belum cukup untuk menukar hadiah ini.';end if;if v_reward.stock is not null then update public.reward_catalog set stock=stock-1,updated_at=now() where id=v_reward.id returning * into v_reward;end if;insert into public.reward_redemptions(user_id,reward_id,reward_name,points_spent,status,redemption_code,redemption_key,fulfilled_at) values(auth.uid(),v_reward.id,v_reward.name,v_reward.cost_points,case when v_reward.fulfillment_type='digital' then 'completed' else 'processing' end,'BP-'||upper(substr(replace(p_redemption_key::text,'-',''),1,8)),p_redemption_key,case when v_reward.fulfillment_type='digital' then now() else null end) returning * into v_redemption;return jsonb_build_object('redemption',to_jsonb(v_redemption),'balance',v_balance-v_reward.cost_points,'remaining_stock',v_reward.stock);end $$;
revoke all on function public.redeem_catalog_reward(text,uuid) from public; grant execute on function public.redeem_catalog_reward(text,uuid) to authenticated; notify pgrst,'reload schema';
